import * as THREE from 'three';
import {autoFitOrthographicBounds} from '../camera-fit.js';
import {STRING_STAGE,HARP_NOTES,stringGripTargets} from './string-pose.js';
function makeBow(){const root=new THREE.Group();root.name='music.held-cello-bow';const wood=new THREE.MeshStandardMaterial({color:'#795637',roughness:.8}),hair=new THREE.MeshStandardMaterial({color:'#f1dfb8',roughness:1});for(const[y,r,m]of[[.021,.018,wood],[0,.005,hair]]){const line=new THREE.Mesh(new THREE.CylinderGeometry(r,r,1.12,8),m);line.rotation.z=Math.PI/2;line.position.set(-.45,y,0);root.add(line);}const grip=new THREE.Mesh(new THREE.BoxGeometry(.12,.055,.055),wood);grip.position.set(.01,.025,0);root.add(grip);return root;}
/** Borrow original player and the room's actual instrument; disposal restores exact transforms. */
export function createStringSession({zoneRoot,player,model,poser,kind='cello',reduced=false}){
 const instrument=zoneRoot?.getObjectByName('music.'+kind),layout=STRING_STAGE[kind];if(!instrument||!layout||!player||!model||!poser)throw Error('StringInstrumentUnavailable');
 const transform=o=>({o,p:o.position.clone(),q:o.quaternion.clone(),s:o.scale.clone(),visible:o.visible}),saved=[player,model,instrument].map(transform),savedPose=poser.getState(),background=zoneRoot.children.filter(o=>o!==instrument&&(o.userData?.species==='music-bird'||o.name==='music.listening-seat'||o.name==='music.headphones-resting'||o.name==='music.'+(kind==='cello'?'harp':'cello'))).map(o=>[o,o.visible]),children=player.children.filter(o=>o!==model).map(o=>[o,o.visible]),resting=instrument.getObjectByName('cello.resting-bow'),restingVisible=resting?.visible;
 const bow=kind==='cello'?makeBow():null,strings=Array.from({length:8},(_,i)=>instrument.getObjectByName('harp.string.'+i)),stringRests=strings.map(s=>s?.position.clone());let alive=true,time=0,selected=0,bowPosition=.5,bowActive=false,pluckAge=1,dirty=true;
 for(const[o]of background)o.visible=false;for(const[o]of children)o.visible=false;if(resting)resting.visible=false;
 instrument.position.fromArray(layout.instrument);instrument.rotation.set(0,0,0);instrument.scale.setScalar(layout.scale);instrument.visible=true;
 zoneRoot.updateWorldMatrix(true,false);const p=zoneRoot.localToWorld(new THREE.Vector3(...layout.player));if(player.parent)player.parent.worldToLocal(p);player.position.copy(p);const q=zoneRoot.getWorldQuaternion(new THREE.Quaternion());if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);player.scale.set(1,1,1);model.position.set(0,0,0);model.quaternion.identity();model.scale.set(1,1,1);if(bow)model.add(bow);
 function pose(){if(!alive)return;const phase=kind==='cello'?bowPosition:selected+(pluckAge<.24&&!reduced?pluckAge/.24*.099:0);poser.setPose(kind,1,phase);if(bow)bow.position.fromArray(poser.getAnchors().rightHand);for(const[s,i]of strings.map((s,i)=>[s,i]))if(s){s.position.copy(stringRests[i]);if(i===selected&&pluckAge<.6&&!reduced)s.position.z+=Math.sin(pluckAge*90)*.017*Math.exp(-pluckAge*8);}player.updateWorldMatrix(true,true);instrument.updateWorldMatrix(true,true);dirty=false;}
 pose();
 return{setNote(midi){if(!alive)return;const i=HARP_NOTES.indexOf(midi);if(i>=0)selected=i;},setBow(value={}){if(!alive)return;bowPosition=THREE.MathUtils.clamp(Number.isFinite(value.position)?value.position:bowPosition,0,1);bowActive=!!value.active;dirty=true;},pluck(midi){if(!alive)return;const i=HARP_NOTES.indexOf(midi);if(i<0)return;selected=i;pluckAge=0;dirty=true;},update(dt=1/60){if(!alive)return;const step=Number.isFinite(dt)?THREE.MathUtils.clamp(dt,0,.05):0;time+=step;if(pluckAge<.6){pluckAge+=step;dirty=true;}if(dirty)pose();},snapshot(){const a=poser.getAnchors(),expected=stringGripTargets(kind,kind==='cello'?bowPosition:selected+(pluckAge<.24&&!reduced?pluckAge/.24*.099:0)),gripError=Math.max(new THREE.Vector3(...a.leftHand).distanceTo(new THREE.Vector3(...expected.left)),new THREE.Vector3(...a.rightHand).distanceTo(new THREE.Vector3(...expected.right)));const face=model.getObjectByName('Cream_oval_face'),faceBox=face?new THREE.Box3().setFromObject(face):new THREE.Box3(),modelBox=new THREE.Box3().setFromObject(model);let faceClearance=Infinity;instrument.traverse(o=>{if(!o.isMesh||!o.visible)return;const b=new THREE.Box3().setFromObject(o),gap=Math.hypot(...['x','y','z'].map(k=>Math.max(0,b.min[k]-faceBox.max[k],faceBox.min[k]-b.max[k])));faceClearance=Math.min(faceClearance,gap);});return{kind,bowPosition,bowActive,selected,gripError,faceClearance,floorMin:modelBox.min.y,time};},dispose(){if(!alive)return;alive=false;if(bow){const geometry=new Set(),materials=new Set();bow.traverse(o=>{if(o.geometry)geometry.add(o.geometry);if(o.material)materials.add(o.material);});geometry.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());bow.removeFromParent();}for(const[s,i]of strings.map((s,i)=>[s,i]))if(s)s.position.copy(stringRests[i]);for(const t of saved){t.o.position.copy(t.p);t.o.quaternion.copy(t.q);t.o.scale.copy(t.s);t.o.visible=t.visible;}for(const[o,v]of[...background,...children])o.visible=v;if(resting)resting.visible=restingVisible;poser.setPose(savedPose.name,savedPose.amount,savedPose.time);player.updateWorldMatrix(true,true);instrument.updateWorldMatrix(true,true);}};
}
export function fitStringCamera(camera,zoneRoot,viewport,kind='cello'){
 const p=STRING_STAGE[kind].player,localBounds=kind==='cello'?[[1.18,.01,-2.43],[3.16,2.02,-.50]]:[[2.80,.01,-2.54],[4.26,1.94,-.64]];zoneRoot.updateWorldMatrix(true,false);camera.position.copy(zoneRoot.localToWorld(new THREE.Vector3(p[0]+3.1,3.25,p[2]+4.8)));camera.up.set(0,1,0);camera.lookAt(zoneRoot.localToWorld(new THREE.Vector3(p[0]-.05,1,p[2]+.42)));camera.updateMatrixWorld(true);const bounds=new THREE.Box3(new THREE.Vector3(...localBounds[0]),new THREE.Vector3(...localBounds[1])).applyMatrix4(zoneRoot.matrixWorld);autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{top:8,right:12,bottom:8,left:12}});camera.updateMatrixWorld(true);return bounds;
}
